DATA = ["ada", "bob", "cy", "dee", "eve", "fay", "gus"]


def fake_api(cursor=None):
    start = int(cursor[1:]) * 3 - 3 if cursor else 0
    items = DATA[start:start + 3]
    more = start + 3 < len(DATA)
    return {"items": items, "next": f"c{start // 3 + 2}" if more else None}


def fetch_all():
    yield from []


print(list(fetch_all()))
